-- Fonte: references/curriculum-ms/educacao-fisica-historia-sociologia-filosofia-referencial-ms-2012.json
INSERT INTO pedagogical_topics(institution_id,discipline_id,parent_id,name,position,grade_range,source_reference)
SELECT d.institution_id,d.id,NULL,'Mundo moderno',3,'2ª série','Referencial Curricular do Ensino Médio de MS (2012) — catálogo revisado' FROM pedagogical_disciplines d WHERE d.name='História' AND d.stage='Ensino Médio' ON CONFLICT DO NOTHING;
INSERT INTO pedagogical_topics(institution_id,discipline_id,parent_id,name,position,grade_range,source_reference)
SELECT d.institution_id,d.id,p0.id,'Renascimento',1,'2ª série','Referencial Curricular do Ensino Médio de MS (2012) — catálogo revisado' FROM pedagogical_disciplines d JOIN pedagogical_topics p0 ON p0.discipline_id=d.id AND lower(p0.name)=lower('Mundo moderno') AND p0.grade_range='2ª série' AND p0.parent_id IS NULL WHERE d.name='História' AND d.stage='Ensino Médio' ON CONFLICT DO NOTHING;
